<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Merchant/reply')}" class="on">商家的评论列表</a>|					<a href="{pigcms{:U('Merchant/shop_and_mall_check_reply')}">外卖商城待审核评论列表</a>|				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td style="width:50%;">						<form action="{pigcms{:U('Merchant/reply')}" method="get">							<input type="hidden" name="c" value="Merchant"/>							<input type="hidden" name="a" value="reply"/>							筛选: <input type="text" name="keyword" id="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype" id="searchtype">								<option value="m_name" <if condition="$_GET['searchtype'] eq 'm_name'">selected="selected"</if>>商家名称</option>								<option value="s_name" <if condition="$_GET['searchtype'] eq 's_name'">selected="selected"</if>>店铺名称</option>								<option value="nickname" <if condition="$_GET['searchtype'] eq 'nickname'">selected="selected"</if>>用户姓名</option>								<option value="phone" <if condition="$_GET['searchtype'] eq 'phone'">selected="selected"</if>>用户电话</option>							</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;							<select name="order_type" id="order_type">								<volist name="selectList" id="sel">								<option value="{pigcms{$key}" <if condition="$_GET['order_type'] eq $key">selected="selected"</if>>{pigcms{$sel}</option>								</volist>							</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;							<input type="submit" value="查询" class="button"/>						</form>					</td>                    <td>                        <a href="javascript:void(0)" onclick="exports()" class="button" style="float:right;margin-right: 10px;">导出订单</a>                    </td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<thead>							<tr>								<th>编号</th>								<th>商家名称</th>								<th>店铺名称</th>								<th>订单编号</th>								<th>用户名</th>								<th>用户电话</th>								<th>评论类型</th>								<th>评论时间</th>								<th>评分</th>								<th>评论内容</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($reply_list)">								<volist name="reply_list" id="vo">									<tr>										<td>{pigcms{$vo.pigcms_id}</td>										<td>{pigcms{$vo.m_name}</td>										<td>{pigcms{$vo.s_name}</td>										<td>{pigcms{$vo.order_id}</td>										<td>{pigcms{$vo.nickname}</td>										<td>{pigcms{$vo.phone}</td>										<td><if condition="$vo['order_type'] eq 1">老餐饮<else />{pigcms{$selectList[$vo['order_type']]}</if></td>										<td><if condition="$vo['add_time']">{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}<else/>无</if></td>										<td class="textcenter">{pigcms{$vo.score}</td>										<td style="width:100px">{pigcms{$vo.comment}</td>										<td class="textcenter">										<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{$vo['url']}','查看订单详情',800,800,true,false,false,false,'detail',true);">订单详情</a> |										<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Merchant/replyinfo',array('reply_id'=>$vo['pigcms_id'],'frame_show'=>true))}','查看详细信息',520,470,true,false,false,false,'detail',true);">查看</a> |										<a href="javascript:void(0);" class="delete_row" parameter="reply_id={pigcms{$vo.pigcms_id}" url="{pigcms{:U('Merchant/replydel')}">删除</a>										</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="10">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="10">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><script>    var ii,file_date,file_url;    var url = "{pigcms{$config.site_url}";    var export_url = "{pigcms{:U('Merchant/export_reply')}";    function exports(){        var order_type = $('#order_type').val(),searchtype = $('#searchtype').val(), keyword = $('#keyword').val();        var param = {};        param['order_type'] = order_type;        if (keyword) {            param['keyword'] = keyword;            param['searchtype'] = searchtype;        }        $.post(export_url,param,function(date){            ii= layer.msg('加载中,请耐心等待,数量越多时间越长', {                icon: 16                ,shade: [0.3, '#000']                ,time:0            });            //此处用setTimeout演示ajax的回调            file_url = url+'/index.php?g=Index&c=ExportFile&a=download_export_file&id='+date.export_id;            file_date = date;            CheckStatus()        },'json')    }    function CheckStatus()    {        date = file_date;        $.post(file_url,{id:date.export_id},function(result){            if(result.error_code==0){                layer.close(ii);                layer.open({                    type: 1,                    title:'下载导出文件',                    area: ['600px', '120px'],                    content: '\<p style="height:18px"\>\<\/p\>\<\a style="font-size:18px;" href="'+url+'/index.php?g=Index&c=ExportFile&a=download_export_file&id='+date.export_id+'" download="'+date.file_name+'">点击下载导出文件\<\/a>'                });                $('.layui-layer-content').css('text-align','center');                $('.layui-layer .layui-anim .layui-layer-page').css('top','200px');            }else{                setTimeout("CheckStatus()",1000);            }        },'json')    }</script><include file="Public:footer"/>